import itertools

def has_cycle_of_length(edges, length, n):
    """Check if there's a cycle of given length"""
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # For small lengths, we can enumerate
    if length == 3:
        for i in range(n):
            for j in adj[i]:
                if j > i:
                    for k in adj[j]:
                        if k > j and k in adj[i]:
                            return True
        return False
    elif length == 4:
        # Check all 4-tuples
        for a in range(n):
            for b in adj[a]:
                if b > a:
                    for c in adj[b]:
                        if c > b:
                            for d in adj[c]:
                                if d > a and d != b and d != c and a in adj[d]:
                                    # Check it's a simple 4-cycle (no chords)
                                    if b in adj[d] or a in adj[c]:
                                        continue
                                    return True
        return False
    elif length == 5:
        # Check all 5-tuples
        for a in range(n):
            for b in adj[a]:
                if b > a:
                    for c in adj[b]:
                        if c > a and c != b:
                            for d in adj[c]:
                                if d > a and d != b and d != c:
                                    for e in adj[d]:
                                        if e > a and e != b and e != c and e != d and a in adj[e]:
                                            # Check no chords
                                            # The cycle is a-b-c-d-e-a
                                            # Chords would be: a-c, a-d, b-d, b-e, c-e
                                            if (a in adj[c] or a in adj[d] or b in adj[d] or b in adj[e] or c in adj[e]):
                                                continue
                                            return True
        return False
    return None

