def has_short_cycle(edges, n):
    """Check if graph has a cycle of length 3, 4, or 5"""
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check triangles
    for i in range(n):
        for j in adj[i]:
            if j > i:
                for k in adj[j]:
                    if k > j and k in adj[i]:
                        return True, 3

    # Check 4-cycles
    # For each pair of vertices, check if they have >= 2 common neighbors
    for i in range(n):
        for j in range(i+1, n):
            common = len(adj[i] & adj[j])
            if common >= 2:
                return True, 4

    # Check 5-cycles
    # A 5-cycle is a path of length 4 where the endpoints are adjacent
    # and all vertices are distinct
    # We can check by looking at paths of length 4
    for a in range(n):
        for b in adj[a]:
            if b > a:
                for c in adj[b]:
                    if c != a:
                        for d in adj[c]:
                            if d != a and d != b:
                                for e in adj[d]:
                                    if e != a and e != b and e != c and e in adj[a]:
                                        # Found a 5-cycle a-b-c-d-e-a
                                        # Check no chords
                                        if (a in adj[c] or a in adj[d] or 
                                            b in adj[d] or b in adj[e] or 
                                            c in adj[e]):
                                            continue
                                        return True, 5
    return False, 0

def is_4_colorable(edges, n):
    """Check if graph is 4-colorable using simple backtracking"""
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(4):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

